"""Chapter 8 Thermal Processes: written-answer questions, 5 per level. Marked by trainer.marker (meaning, not exact words).
Each item: marking points (label shown to the student as a cue; alternative phrasings), pitfalls (wrong ideas, ordered phrases),
model answer, 3 hints, key words, and sample answers the tests must pass / fail."""
from .. import sketches
from ..marker import Pitfall, Point
from .base import written

P = Point
PF = Pitfall

# ---------------------------------------------------------------- L1: state / define
written("w8_direction", 8, 1, "8a",
        stem="State the direction in which energy is transferred by heating when two bodies at different temperatures are in contact.",
        points=[P("from the hotter body to the colder body",
                  ["hot to cold", "hotter to colder", "higher temperature to lower temperature", "high temperature to low temperature",
                   "warmer to cooler", "hot object to cold object", "hot body to cold body", "from the hotter", "to the colder"])],
        pitfalls=[PF(["cold to hot", "colder to hotter", "lower temperature to higher", "cold flows", "cold enters", "cold moves"],
                     "Energy always moves from the hotter body to the colder one. 'Cold' does not flow.")],
        model_answer="Energy is transferred from the body at the higher temperature to the body at the lower temperature.",
        hints=["Think of a hot spoon in cold water. Which one warms up?",
               "Energy leaves the body that is at the higher temperature.",
               "Write: from the ___ temperature body to the ___ temperature body."],
        keywords="higher temperature → lower temperature",
        sample_pass=["From the hoter object to the colder object", "energy goes from high temperature to low temperature"],
        sample_fail=["It moves from cold to hot", "between them", "hot"])

written("w8_thermal_equilibrium", 8, 1, "8a",
        stem="What is meant by two bodies being in thermal equilibrium?",
        points=[P("they are at the same temperature (so there is no net transfer of energy)",
                  ["same temperature", "equal temperature", "temperatures are equal", "temperature is the same", "no net transfer",
                   "no net flow", "no more transfer", "stops transferring", "no longer transferred"])],
        model_answer="The two bodies are at the same temperature, so there is no net transfer of energy between them.",
        hints=["Energy is transferred because of a temperature DIFFERENCE. When does that stop?",
               "It stops when there is no longer a difference.",
               "They are at the ___ temperature, so no net energy is transferred."],
        keywords="same temperature, no net transfer",
        sample_pass=["Both objects have reached the same temprature", "There is no net transfer of energy between them"],
        sample_fail=["They are both hot", "energy is transferred quickly"])

written("w8_name_conduction", 8, 1, "8b",
        stem="Fig. 1 shows a metal rod heated at one end. Name the process by which energy is transferred along the rod.",
        points=[P("conduction", ["conduction", "conducted", "conducts", "thermal conduction"])],
        pitfalls=[PF(["convection"], "Convection needs a moving fluid. In a solid rod the particles cannot flow, so think of the process that works in solids.")],
        model_answer="Conduction.",
        hints=["The rod is a solid. Which thermal process happens in solids?",
               "It involves vibrating atoms and free electrons passing energy along.",
               "It begins with 'con' and is not convection."],
        keywords="conduction",
        figure=lambda: sketches.rod_sketch(["metal"]),
        sample_pass=["This is conducton", "energy is conducted along the rod"],
        sample_fail=["convection", "radiation"])

written("w8_name_radiation", 8, 1, "8d",
        stem="Name the process of energy transfer that does not require a material medium.",
        points=[P("radiation (infrared / electromagnetic waves)", ["radiation", "radiate", "infrared", "electromagnetic waves"])],
        pitfalls=[PF(["conduction"], "Conduction needs particles in contact."), PF(["convection"], "Convection needs a fluid to move.")],
        model_answer="Radiation (energy carried by infrared electromagnetic waves).",
        hints=["Which process brings energy from the Sun to the Earth through empty space?",
               "It travels as waves, not through particles.",
               "It is called ___ (the waves are infrared)."],
        keywords="radiation",
        sample_pass=["Radiaton", "infrared radiation"],
        sample_fail=["conduction", "convection currents"])

written("w8_radiation_factor", 8, 1, "8d",
        stem="State one factor that affects the rate at which a body emits infrared radiation.",
        points=[P("one of: surface colour, surface texture, surface temperature, surface area",
                  ["colour", "color", "black", "dark", "white", "texture", "dull", "matt", "shiny", "rough", "smooth",
                   "temperature", "surface area", "area"])],
        model_answer="The surface colour (dull black emits most), the surface texture, the surface temperature, or the surface area.",
        hints=["Think about what the SURFACE of the body is like, and how hot it is.",
               "A dull black kettle and a shiny one at the same temperature do not emit equally.",
               "Colour, texture, temperature or ___ area."],
        keywords="colour, texture, temperature, surface area",
        sample_pass=["the colour of the surface", "how large its surface area is", "its temperature"],
        sample_fail=["its mass", "the density of the body"])

# ---------------------------------------------------------------- L2: two facts / simple description
written("w8_conduction_particles", 8, 2, "8b",
        stem="Fig. 1 shows a metal rod heated at one end. Describe, in terms of particles, how energy is transferred along the rod.",
        points=[P("atoms vibrate more and pass on the vibration to neighbouring atoms",
                  ["vibrate", "vibration", "vibrating", "collide with neighbouring", "pass on to neighbouring", "knock neighbouring"]),
                P("free electrons move through the metal carrying energy",
                  ["free electrons", "electrons move", "electrons carry", "electrons travel", "mobile electrons", "electrons diffuse"])],
        model_answer="The atoms at the hot end vibrate more vigorously and pass on the vibrations to neighbouring atoms. Free electrons gain energy, move through the metal and transfer energy as they collide with atoms.",
        hints=["Two things carry energy along a metal. One is what the atoms do; the other is a type of particle only metals have free.",
               "Heated atoms vibrate more and jostle their neighbours. What else moves freely in a metal?",
               "Atoms ___ more vigorously; free ___ carry energy through the metal."],
        keywords="vibrate, neighbouring atoms, free electrons",
        figure=lambda: sketches.rod_sketch(["metal"]),
        sample_pass=["The atoms vibrat more and bump into neighbouring atoms, and the free electrons move along carrying the energy",
                     "particles vibrate faster passing it on, electrons that are free travel through the rod"],
        sample_fail=["The hot air rises along the rod", "The atoms vibrate more"])

written("w8_conduction_vs_radiation", 8, 2, "8d",
        stem="State two differences between conduction and radiation.",
        points=[P("radiation needs no medium / conduction needs particles",
                  ["no medium", "without a medium", "through a vacuum", "needs particles", "needs a medium", "requires a medium", "empty space", "needs matter"]),
                P("radiation is electromagnetic waves / conduction is by vibrating particles and electrons",
                  ["electromagnetic", "infrared", "waves", "vibrating particles", "vibrations", "free electrons", "speed of light", "much faster"])],
        model_answer="Radiation does not need a medium and can travel through a vacuum, but conduction needs particles. Radiation is carried by infrared electromagnetic waves, whereas conduction is by vibrating particles and free electrons.",
        hints=["Think about WHAT carries the energy in each case, and WHERE each can happen.",
               "Can either of them work in empty space?",
               "Radiation: no ___ needed, travels as ___. Conduction: needs particles."],
        keywords="medium, vacuum, electromagnetic waves, vibrating particles",
        sample_pass=["Radiation can travel through a vacuum but conduction needs particles. Radiation is infrared waves while conduction is vibrations",
                     "conduction requires a medium, radiation does not; radiation uses electromagnetic waves"],
        sample_fail=["Conduction is slower", "They are both ways of transferring heat"])

written("w8_convection_at_A", 8, 2, "8c",
        stem="Fig. 1 shows water in a beaker heated at the bottom left. Describe what happens to the water at A.",
        points=[P("the water is heated and expands", ["expands", "expand", "spreads out", "particles move apart", "takes up more space"]),
                P("it becomes less dense", ["less dense", "lower density", "density decreases", "density falls", "density is lower", "lighter"]),
                P("so it rises", ["rises", "rise", "moves up", "goes up", "floats up", "upwards"])],
        min_points=2,
        pitfalls=[PF(["more dense", "denser", "density increases"], "Heated water EXPANDS, so its density falls; denser water sinks."),
                  PF(["heat rises"], "It is the hot, less dense WATER that rises, not 'heat'.")],
        model_answer="The water at A is heated, so it expands and becomes less dense than the cooler water around it. It therefore rises.",
        hints=["A is right above the heat. What happens to the volume of water when it is heated?",
               "If the same mass takes up more volume, what happens to its density?",
               "Less dense water ___ ."],
        keywords="expands, less dense, rises",
        figure=lambda: sketches.convection_sketch(),
        sample_pass=["The water gets hot, expands and becomes less dense so it rises", "it is heated so its density decreases and it moves upwards"],
        sample_fail=["The water gets hotter", "it becomes denser and rises"])

written("w8_black_vs_silver_emission", 8, 2, "8d",
        stem="Fig. 1 shows two cups of hot water at the same temperature, one dull black and one shiny silver. Compare the rates at which they emit infrared radiation.",
        points=[P("the dull black cup emits faster / is the better emitter",
                  ["black emits more", "black emits faster", "black better emitter", "black higher rate", "black radiates more", "black loses more", "black cools faster", "black good emitter"]),
                P("the shiny silver cup emits more slowly / is a poor emitter",
                  ["silver emits less", "silver poor emitter", "shiny poor emitter", "silver slower", "silver lower rate", "shiny emits less", "silver cools slower", "silver radiates less"])],
        model_answer="The dull black cup emits infrared radiation at a higher rate; the shiny silver cup is a poor emitter and emits more slowly.",
        hints=["Which kind of surface is the best emitter of radiation?",
               "Dull black surfaces are good emitters AND good absorbers. Shiny surfaces are poor at both.",
               "Black: ___ rate of emission. Silver: ___ rate."],
        keywords="dull black good emitter, shiny silver poor emitter",
        figure=lambda: sketches.two_cups_sketch(note="same temperature"),
        sample_pass=["The black cup emits radiation faster and the silver cup emits less", "dull black is a better emitter; shiny silver is a poor emitter"],
        sample_fail=["They emit at the same rate because they are at the same temperature", "the black one is hotter"])

written("w8_spoon_handle", 8, 2, "8e",
        stem="A metal spoon is left standing in a bowl of hot soup. Explain why the handle soon feels hot.",
        points=[P("energy is conducted along the metal", ["conduct", "conduction", "conducted", "conductor", "conducts"]),
                P("by vibrating atoms passing on energy and/or free electrons", ["vibrat", "free electrons", "electrons", "neighbouring atoms", "pass on energy", "good conductor"])],
        pitfalls=[PF(["convection"], "The spoon is a solid; its particles cannot flow, so this is conduction, not convection.")],
        model_answer="Energy is conducted along the metal spoon: the atoms in the hot end vibrate more and pass the vibration to their neighbours, and free electrons carry energy quickly to the handle.",
        hints=["The spoon is a solid. Which process moves energy through a solid?",
               "Metals are good conductors. What makes them so good?",
               "Energy is ___ along the spoon by vibrating atoms and free ___ ."],
        keywords="conduction, free electrons, vibrations",
        sample_pass=["Heat is conducted along the spoon by free electrons", "metal is a good conductor so energy is passed on by vibrating atoms"],
        sample_fail=["Hot soup rises up the spoon by convection", "The soup is hot"])

# ---------------------------------------------------------------- L3: explain with a reason
written("w8_copper_pin_first", 8, 3, "8b",
        stem="Fig. 1 shows rods of copper, iron and glass heated equally at one end. Pins are stuck to each rod with wax. Explain why the pin on the copper rod falls first.",
        points=[P("copper is the best conductor of the three", ["copper better conductor", "copper best conductor", "copper good conductor", "copper conducts faster", "copper conducts better", "copper is a better"]),
                P("energy reaches the wax on the copper rod sooner", ["reaches the wax", "wax melts first", "wax melts sooner", "melts the wax", "faster along", "quicker along", "sooner"]),
                P("because of free electrons (more mobile) and vibrations", ["free electrons", "electrons", "vibrations", "vibrating"])],
        min_points=2,
        model_answer="Copper is the best conductor of the three, because its free electrons transfer energy quickly as well as the vibrating atoms. Energy therefore reaches the wax on the copper rod first, melting it so the pin falls.",
        hints=["All three rods receive the same heating. What differs is how FAST energy travels along each one.",
               "Which material conducts best, and what carries the energy in a metal besides vibrating atoms?",
               "Copper is the ___ conductor, so the wax on it ___ first."],
        keywords="best conductor, free electrons, wax melts first",
        figure=lambda: sketches.rod_sketch(["copper", "iron", "glass"]),
        sample_pass=["Copper is a better conductor than iron and glass so the energy reaches the wax sooner and melts it",
                     "copper conducts faster because of free electrons so the wax melts first"],
        sample_fail=["Copper is heavier so it heats up faster", "The flame is nearer the copper rod"])

written("w8_room_heater_convection", 8, 3, "8c",
        stem="Fig. 1 shows a convection current. A heater is placed near the floor of a room. Explain how it warms the whole room.",
        points=[P("air near the heater is heated, expands and becomes less dense", ["expands", "less dense", "lower density", "density decreases"]),
                P("the warm air rises", ["rises", "moves up", "goes up", "upwards"]),
                P("cooler, denser air sinks and moves in to replace it, setting up a convection current", ["cooler air sinks", "cold air sinks", "denser air sinks", "replaces", "takes its place", "moves in", "convection current", "circulates", "circulation"])],
        min_points=2,
        pitfalls=[PF(["heat rises"], "It is the warm AIR that rises because it is less dense; 'heat' is not a substance.")],
        model_answer="Air near the heater is warmed, expands and becomes less dense, so it rises. Cooler, denser air sinks and moves in to take its place, is warmed in turn, and a convection current circulates warm air around the room.",
        hints=["This is convection in a fluid (air). Start with what happens to the air touching the heater.",
               "Warm air expands, becomes less dense and rises. What fills the space it leaves?",
               "Warm air ___; cooler denser air ___ and replaces it, forming a convection ___ ."],
        keywords="expands, less dense, rises, cooler air sinks, convection current",
        figure=lambda: sketches.convection_sketch(),
        sample_pass=["The air above the heater expands and becomes less dense so it rises, and cooler denser air sinks to take its place forming a convection current",
                     "hot air rises as it is less dense, cold air moves in to replace it and gets heated"],
        sample_fail=["The heater radiates heat to all parts of the room", "Heat rises"])

written("w8_kettle_element", 8, 3, "8c",
        stem="Explain why the heating element of an electric kettle is placed near the bottom.",
        points=[P("the water near the element is heated, expands, becomes less dense and rises", ["less dense", "expands", "rises", "density"]),
                P("cooler, denser water sinks to the element and is heated in turn", ["cooler water sinks", "cold water sinks", "denser water sinks", "sinks to the bottom", "replaces", "takes its place", "moves down"]),
                P("so a convection current heats all the water", ["convection current", "all the water", "whole", "evenly", "circulat", "entire"])],
        min_points=2,
        model_answer="Water heated at the bottom expands, becomes less dense and rises; cooler, denser water sinks to the element and is heated in turn. This convection current heats all the water. An element at the top would only heat the water above it.",
        hints=["Think about convection. Which way does heated water move?",
               "If hot water rises, where must the heating start so that the water circulates?",
               "Hot water ___; cold water ___ to the element; a convection ___ heats all the water."],
        keywords="expands, less dense, rises, cold water sinks, convection current",
        sample_pass=["Water at the bottom is heated, becomes less dense and rises while colder water sinks, so a convection current heats the whole kettle",
                     "the hot water expands and rises and cool denser water moves down to be heated so all the water warms up"],
        sample_fail=["Because the element must be covered by water", "the bottom is the strongest part of the kettle"])

written("w8_air_poor_conductor", 8, 3, "8b",
        stem="Fig. 1 shows the particles in air. Explain, in terms of particles, why air is a poor conductor of heat.",
        points=[P("the particles in air are far apart", ["far apart", "widely spaced", "spread out", "large spaces", "low density", "not close"]),
                P("so they collide and pass on energy rarely / there are no free electrons", ["collide less", "rarely collide", "fewer collisions", "pass on energy slowly", "slowly", "no free electrons", "cannot pass"])],
        model_answer="The particles in a gas are far apart, so they collide with each other only rarely and energy is passed on very slowly. There are also no free electrons to carry energy.",
        hints=["Conduction works by particles passing energy to their neighbours. How close are the particles in a gas?",
               "Far-apart particles rarely bump into each other.",
               "Particles are far ___, so energy is passed on ___ ."],
        keywords="particles far apart, few collisions, no free electrons",
        figure=lambda: sketches.particles("gas", "air"),
        sample_pass=["The air particles are far apart so they rarely collide and pass energy on slowly", "gas molecules are spread out and there are no free electrons"],
        sample_fail=["Air is a gas", "air is light and rises"])

written("w8_black_cup_cools", 8, 3, "8d",
        stem="Fig. 1 shows two identical cups of hot tea, one dull black and one shiny silver. Explain which cup of tea cools faster.",
        points=[P("the black cup cools faster", ["black cools faster", "black cup cools", "black one cools quicker", "black loses energy faster", "black faster", "black tea cools"]),
                P("because a dull black surface is a better emitter of infrared radiation", ["better emitter", "good emitter", "emits more", "emits faster", "radiates more", "radiation"])],
        pitfalls=[PF(["silver cools faster", "shiny cools faster"], "Shiny surfaces are poor emitters, so the silver cup keeps its energy longer.")],
        model_answer="The tea in the dull black cup cools faster because a dull black surface is a better emitter of infrared radiation than a shiny silver surface.",
        hints=["Both cups are at the same temperature at the start. What differs is how fast each surface loses energy by radiation.",
               "Which surface is the better emitter?",
               "The ___ cup cools faster because it is a better ___ of radiation."],
        keywords="dull black better emitter, radiation",
        figure=lambda: sketches.two_cups_sketch(note="hot tea, same temperature"),
        sample_pass=["The black cup cools faster because dull black is a good emitter of infrared", "the dull black one loses energy faster as it radiates more"],
        sample_fail=["The silver cup cools faster because metal conducts", "They cool at the same rate"])

# ---------------------------------------------------------------- L4: chains of reasoning
written("w8_flask_vacuum", 8, 4, "8e",
        stem="Fig. 1 shows a vacuum flask. Explain how the vacuum between the two glass walls reduces energy loss from the hot liquid.",
        points=[P("a vacuum contains no particles", ["no particles", "no matter", "no air", "nothing in it", "empty", "no medium"]),
                P("so conduction cannot happen through it", ["conduction", "conducted", "conduct"]),
                P("and convection cannot happen either (no fluid to move)", ["convection", "convect"])],
        min_points=2,
        pitfalls=[PF(["vacuum stops radiation", "vacuum prevents radiation", "vacuum reduces radiation", "vacuum blocks radiation"],
                     "Radiation CAN cross a vacuum. That is why the walls are silvered. The vacuum stops conduction and convection.")],
        model_answer="The vacuum contains no particles, so energy cannot be transferred across it by conduction (which needs particles in contact) or by convection (which needs a fluid to move). Only radiation can cross it, and that is reduced by the silvered surfaces.",
        hints=["Which two methods of transfer need particles to work?",
               "A vacuum has no particles at all. So which processes are impossible across it?",
               "No particles → no ___ and no ___ ."],
        keywords="no particles, conduction, convection",
        figure=lambda: sketches.flask_sketch(),
        sample_pass=["There are no particles in the vacuum so conduction and convection cannot take place", "a vacuum is empty so energy cannot be conducted or convected across it"],
        sample_fail=["The vacuum stops radiation escaping", "The vacuum keeps the heat in"])

written("w8_flask_silver", 8, 4, "8e",
        stem="Fig. 1 shows a vacuum flask. Explain why the inner surfaces of the glass walls are silvered.",
        points=[P("shiny surfaces are poor emitters of infrared radiation", ["poor emitter", "emits less", "poor radiator", "reduce emission", "less radiation emitted", "does not emit"]),
                P("and they reflect radiation back towards the liquid", ["reflect", "reflects", "reflected", "bounce back", "poor absorber"]),
                P("radiation is the only process that can cross the vacuum", ["cross the vacuum", "through the vacuum", "only radiation", "radiation can still", "across the vacuum"])],
        min_points=2,
        model_answer="Energy can still cross the vacuum by radiation. The shiny silvered surfaces are poor emitters, so little infrared is radiated from the hot inner wall, and they reflect any radiation back towards the liquid.",
        hints=["The vacuum stops conduction and convection. Which process is left, and what kind of surface reduces it?",
               "Shiny surfaces are poor emitters and good reflectors.",
               "Silvered surfaces are poor ___ and ___ radiation back."],
        keywords="poor emitter, reflects radiation, radiation crosses vacuum",
        figure=lambda: sketches.flask_sketch(),
        sample_pass=["Silver is a poor emitter of radiation and reflects it back into the liquid", "radiation can cross the vacuum but the shiny surface reflects it back"],
        sample_fail=["Silver is a good conductor so it keeps the liquid warm", "It looks nice"])

written("w8_sea_breeze", 8, 4, "8c",
        stem="On a hot sunny day a breeze blows from the sea towards the land. Explain why.",
        points=[P("land heats up faster than the sea", ["land heats faster", "land warms faster", "land gets hotter", "land is hotter", "land heats up more", "land warms up quicker", "sea heats slowly"]),
                P("air above the land is warmed, expands, becomes less dense and rises", ["less dense", "expands", "rises", "density"]),
                P("cooler denser air from over the sea moves in to replace it", ["from the sea moves", "from over the sea", "sea moves in", "replaces", "takes its place", "moves towards the land", "cooler air moves"])],
        min_points=2,
        model_answer="Land heats up faster than the sea. The air above the land is warmed, expands, becomes less dense and rises. Cooler, denser air from over the sea moves in to take its place, which is felt as a breeze from the sea to the land.",
        hints=["This is a convection current on a large scale. Which heats up faster in sunshine: land or water?",
               "Air above the warmer surface rises. What moves in to replace it?",
               "Land heats ___; air above it ___; cooler air from the sea ___ ."],
        keywords="land heats faster, air rises, cooler air from sea replaces",
        sample_pass=["The land heats up faster than the sea, the air above it becomes less dense and rises, and cooler air from the sea moves in to replace it",
                     "land warms quicker so air over it rises and air from over the sea takes its place"],
        sample_fail=["The sea is cold so wind blows from it", "Waves push the air towards the land"])

written("w8_light_clothing", 8, 4, "8d",
        stem="Explain why wearing light-coloured clothing keeps a person cooler in strong sunshine than wearing dark clothing.",
        points=[P("light-coloured surfaces reflect more of the Sun's radiation / absorb less", ["reflect", "reflects", "absorb less", "poor absorber", "absorbs less"]),
                P("dark surfaces absorb more radiation", ["dark absorbs more", "black absorbs more", "good absorber", "dark absorb", "absorbs more"]),
                P("so less energy is transferred to the person's body", ["less energy", "less heat", "body stays cooler", "does not heat up as much", "warms less", "cooler"])],
        min_points=2,
        model_answer="Light-coloured surfaces reflect most of the Sun's radiation and absorb little, whereas dark surfaces are good absorbers. Less energy is therefore transferred to the body under light clothing, so the person stays cooler.",
        hints=["Sunlight carries energy as radiation. What do light and dark surfaces do differently with it?",
               "Dark surfaces are good absorbers; light surfaces are good reflectors.",
               "Light clothes ___ radiation, dark clothes ___ it, so less energy reaches the ___ ."],
        keywords="reflect, absorb, radiation",
        sample_pass=["Light colours reflect the radiation while dark colours absorb it so less energy reaches the body", "white reflects more sunlight and absorbs less so the person stays cooler"],
        sample_fail=["Light clothes are thinner", "Dark clothes are heavier to wear"])

written("w8_metal_feels_cold", 8, 4, "8e",
        stem="A metal door handle and a wooden door handle are both at room temperature. Explain why the metal handle feels colder to the touch.",
        points=[P("metal is a much better conductor than wood", ["metal better conductor", "metal good conductor", "metal conducts", "wood poor conductor", "wood is an insulator", "wood insulator", "good conductor"]),
                P("so energy is conducted away from the hand faster", ["away from the hand", "away from your hand", "from the hand", "from your skin", "faster from", "quickly from", "out of your hand", "leaves your hand"]),
                P("both handles are actually at the same temperature", ["same temperature", "both at room temperature", "not actually colder", "equal temperature"])],
        min_points=2,
        pitfalls=[PF(["metal is colder", "metal has a lower temperature", "metal is at a lower temperature"], "Both handles are at room temperature. The metal only FEELS colder because it conducts energy away from your hand faster.")],
        model_answer="Both handles are at the same temperature, but metal is a much better conductor than wood. It conducts energy away from the warmer hand quickly, so the hand loses energy fast and the handle feels cold. Wood conducts slowly, so little energy leaves the hand.",
        hints=["Both handles are at room temperature, so the difference is not temperature. What does your hand lose when it touches each one?",
               "Your hand is warmer than the handle. Which material carries energy away from it faster?",
               "Metal is a better ___, so energy leaves your hand ___ ."],
        keywords="good conductor, energy conducted away from the hand, same temperature",
        sample_pass=["Metal is a better conductor so it conducts energy away from your hand faster, even though both are at the same temperature",
                     "wood is a poor conductor so little energy leaves the hand, but metal conducts it away quickly"],
        sample_fail=["The metal is colder than the wood", "Metal is harder than wood"])

# ---------------------------------------------------------------- L5: apply / evaluate
written("w8_coat_keeps_cold_out", 8, 5, "8e",
        stem="A student says that a thick coat 'keeps the cold out'. Evaluate this statement using ideas about thermal energy transfer.",
        points=[P("the coat reduces energy transfer FROM the body to the surroundings", ["from the body", "from your body", "leaving the body", "body losing", "losing energy", "energy loss from", "keeps the heat in", "escaping from"]),
                P("it traps air, which is a poor conductor", ["traps air", "trapped air", "air is a poor conductor", "air pockets", "layer of air", "insulator"]),
                P("and the trapped air cannot circulate, reducing convection", ["cannot circulate", "convection", "cannot move", "stops the air moving"])],
        min_points=2,
        pitfalls=[PF(["cold enters", "cold gets in", "cold comes in", "stops the cold entering", "cold from entering", "cold from getting in"],
                     "Cold is not a substance that moves. The coat slows energy leaving the warm body.")],
        model_answer="The statement is wrong in its physics: 'cold' does not flow. The coat reduces the rate at which energy is transferred from the warm body to the cooler surroundings. It traps a layer of air, which is a poor conductor, and the trapped air cannot circulate, so convection is reduced too.",
        hints=["Which way does energy move: from the cold air into you, or from you to the cold air?",
               "A coat traps air. What is air like as a conductor, and can trapped air form convection currents?",
               "The coat slows energy leaving the ___; trapped ___ is a poor conductor and cannot ___ ."],
        keywords="energy leaves the body, trapped air poor conductor, convection reduced",
        sample_pass=["The coat does not keep cold out; it reduces the energy lost from the body because the trapped air is a poor conductor",
                     "cold does not move. the coat traps a layer of air which insulates and stops convection so the body loses energy more slowly"],
        sample_fail=["Yes, the coat stops the cold getting in", "The coat is thick"])

written("w8_solar_heater", 8, 5, "8e",
        stem="A solar water heater has copper pipes painted matt black, fixed to a black panel under a glass cover. Explain the purpose of two of these design features.",
        points=[P("matt black surfaces absorb radiation well", ["black absorbs", "matt black", "good absorber", "absorbs more", "absorbs radiation", "dull black"]),
                P("copper conducts energy quickly to the water", ["copper conducts", "good conductor", "conducts quickly", "copper is a good"]),
                P("the glass cover traps warm air and reduces convection / lets radiation in but reduces re-emission", ["glass traps", "traps air", "reduces convection", "stops convection", "lets radiation in", "lets sunlight in", "glass cover", "greenhouse"])],
        min_points=2,
        model_answer="The matt black surfaces are good absorbers of the Sun's radiation. Copper is a good conductor, so energy passes quickly into the water. The glass cover lets radiation in but traps the warm air, reducing energy loss by convection.",
        hints=["Each feature targets one process: absorbing radiation, conducting energy, or stopping losses.",
               "Why black? Why copper? Why a glass lid?",
               "Black ___ radiation; copper ___ energy to the water; glass traps ___ and reduces convection."],
        keywords="black good absorber, copper good conductor, glass reduces convection",
        sample_pass=["Matt black absorbs radiation well and copper conducts the energy to the water quickly", "the black panel is a good absorber and the glass traps warm air to reduce convection"],
        sample_fail=["Black looks hot and copper is strong", "The glass stops rain getting in"])

written("w8_radiator_low", 8, 5, "8c",
        stem="Fig. 1 shows a convection current. Household 'radiators' are placed low on a wall. Explain why they warm a room mainly by convection and why the low position helps.",
        points=[P("air in contact with the radiator is heated, expands, becomes less dense and rises", ["less dense", "expands", "rises", "warm air rises", "hot air rises"]),
                P("cooler denser air sinks and replaces it, forming a convection current", ["cooler air sinks", "cold air sinks", "denser air sinks", "replaces", "convection current", "circulat"]),
                P("placing it low lets the warm air rise through the whole room", ["whole room", "entire room", "rise through the room", "circulate round the room", "all of the room", "if it were high"])],
        min_points=2,
        model_answer="Air touching the radiator is warmed, expands, becomes less dense and rises; cooler, denser air sinks and moves in to replace it, so a convection current circulates. Placing the radiator low means the warm air rises through the whole room instead of staying trapped near the ceiling.",
        hints=["What happens to the air that touches the hot radiator?",
               "Warm air rises. If the radiator were near the ceiling, where would the warm air stay?",
               "Warm air ___; cool air ___; from a low position the current fills the ___ room."],
        keywords="warm air rises, cool air sinks, convection current, whole room",
        figure=lambda: sketches.convection_sketch(),
        sample_pass=["The air next to it gets less dense and rises while cooler air sinks to replace it, so from low down the warm air can circulate through the whole room",
                     "hot air rises and cold air sinks making a convection current; if it were high the warm air would stay near the ceiling"],
        sample_fail=["Radiators radiate heat across the room", "It is easier to fit them low down"])

written("w8_double_glazing", 8, 5, "8e",
        stem="A double-glazed window has two panes of glass with a narrow gap of air between them. Explain how this reduces energy loss, and why the gap is kept narrow.",
        points=[P("air is a poor conductor, so conduction through the window is reduced", ["air is a poor conductor", "air poor conductor", "air insulator", "trapped air", "reduces conduction", "poor conductor"]),
                P("a narrow gap stops the air circulating, so convection is reduced", ["narrow gap", "cannot circulate", "convection", "convection current", "air cannot move", "too small"]),
                P("a wide gap would allow convection currents", ["wide gap", "wider gap", "large gap", "would allow convection", "convection currents would"])],
        min_points=2,
        model_answer="The trapped air is a poor conductor, so less energy is conducted through the window than through a single pane. The gap is narrow so the air cannot circulate: a wide gap would let convection currents form and carry energy across.",
        hints=["Two processes are being reduced: one by the air itself, one by the SIZE of the gap.",
               "Air is a poor conductor. But air can move: what would happen in a wide gap?",
               "Air reduces ___; a narrow gap prevents ___ currents."],
        keywords="air poor conductor, narrow gap prevents convection",
        sample_pass=["The air between the panes is a poor conductor and the narrow gap stops convection currents forming", "trapped air insulates; if the gap were wide the air would circulate by convection"],
        sample_fail=["Two panes are stronger than one", "The air keeps the cold out"])

written("w8_foil_ice", 8, 5, "8d",
        stem="Ice cubes wrapped in shiny aluminium foil melt more slowly than unwrapped ice cubes in the same warm room. Explain why.",
        points=[P("the shiny foil reflects infrared radiation from the room / is a poor absorber", ["reflects", "reflect", "poor absorber", "absorbs less", "does not absorb"]),
                P("so less energy reaches the ice by radiation", ["less energy reaches", "less radiation reaches", "less energy is absorbed", "less energy transferred", "slows the transfer", "gains energy more slowly"]),
                P("the foil also traps a layer of air, reducing conduction and convection", ["traps air", "layer of air", "reduces convection", "reduces conduction", "air is a poor conductor"])],
        min_points=2,
        pitfalls=[PF(["keeps the cold in", "keeps cold in", "cold cannot escape"], "Cold does not escape. The foil slows energy from the warm room reaching the ice.")],
        model_answer="The shiny foil is a poor absorber and reflects most of the infrared radiation from the warm room, so less energy reaches the ice by radiation. The foil also traps a thin layer of air, which reduces conduction and convection. The ice therefore gains energy more slowly and melts more slowly.",
        hints=["Energy must travel from the warm room INTO the ice for it to melt. Which process does a shiny surface interfere with?",
               "Shiny surfaces are poor absorbers and good reflectors of radiation.",
               "Foil ___ radiation, so ___ energy reaches the ice."],
        keywords="reflects radiation, poor absorber, less energy reaches the ice",
        sample_pass=["The shiny foil reflects the infrared radiation from the room so less energy reaches the ice", "foil is a poor absorber of radiation and traps air so the ice gains energy more slowly"],
        sample_fail=["The foil keeps the cold in", "Foil is made of metal"])
